`timescale 1ns / 1ps

// Automatically generated by EC551 HLS tool
// Each step pulse advances exactly one FSM state

module generated_step_circuit (
    input wire clk,
    input wire reset,
    input wire step,
    input wire [15:0] A,
    input wire [15:0] B,
    output reg done,
    output wire [15:0] out_X,
    output wire [15:0] out_Y,
    output wire [15:0] out_Z,
    output wire [15:0] out_Q,
    input wire [7:0] observe_index,
    input wire [1:0] observe_type,
    output reg [15:0] observe_data
);

  reg [2:0] state;

  localparam [2:0] IDLE = 0;
  localparam [2:0] DONE = 4;
  localparam [2:0] CYCLE_1 = 1;
  localparam [2:0] CYCLE_2 = 2;
  localparam [2:0] CYCLE_3 = 3;

  // Intermediate registers
  reg [15:0] reg_X_1;
  reg [15:0] reg_Y_1;
  reg [15:0] reg_Z_1;
  reg [15:0] reg_Q_1;

  reg [15:0] adder_0_a;
  reg [15:0] adder_0_b;
  wire [15:0] adder_0_result;

  adder #(.WIDTH(16)) u_adder_0 (
    .a(adder_0_a),
    .b(adder_0_b),
    .result(adder_0_result)
  );

  always @(*) begin
    adder_0_a = 16'd0;
    adder_0_b = 16'd0;

    case (state)
      CYCLE_1: begin
        adder_0_a = A;
        adder_0_b = B;
      end
      CYCLE_2: begin
        adder_0_a = reg_X_1;
        adder_0_b = A;
      end
      default: begin end
    endcase
  end

  reg [15:0] multiplier_0_a;
  reg [15:0] multiplier_0_b;
  wire [15:0] multiplier_0_result;

  multiplier #(.WIDTH(16)) u_multiplier_0 (
    .a(multiplier_0_a),
    .b(multiplier_0_b),
    .result(multiplier_0_result)
  );

  always @(*) begin
    multiplier_0_a = 16'd0;
    multiplier_0_b = 16'd0;

    case (state)
      CYCLE_3: begin
        multiplier_0_a = B;
        multiplier_0_b = reg_Z_1;
      end
      default: begin end
    endcase
  end

  reg [15:0] subtractor_0_a;
  reg [15:0] subtractor_0_b;
  wire [15:0] subtractor_0_result;

  subtractor #(.WIDTH(16)) u_subtractor_0 (
    .a(subtractor_0_a),
    .b(subtractor_0_b),
    .result(subtractor_0_result)
  );

  always @(*) begin
    subtractor_0_a = 16'd0;
    subtractor_0_b = 16'd0;

    case (state)
      CYCLE_2: begin
        subtractor_0_a = reg_X_1;
        subtractor_0_b = B;
      end
      default: begin end
    endcase
  end

  // FSM advances only on a step pulse
  always @(posedge clk) begin

    if (reset) begin
      state <= IDLE;
      done <= 1'b0;
      reg_X_1 <= 16'd0;
      reg_Y_1 <= 16'd0;
      reg_Z_1 <= 16'd0;
      reg_Q_1 <= 16'd0;
    end

    else if (step) begin

      case (state)

        IDLE: begin
          done <= 1'b0;
          state <= CYCLE_1;
        end

        CYCLE_1: begin
          reg_X_1 <= adder_0_result;
          state <= CYCLE_2;
        end

        CYCLE_2: begin
          reg_Y_1 <= adder_0_result;
          reg_Z_1 <= subtractor_0_result;
          state <= CYCLE_3;
        end

        CYCLE_3: begin
          reg_Q_1 <= multiplier_0_result;
          done <= 1'b1;
          state <= DONE;
        end

        DONE: begin
          done <= 1'b0;
          state <= IDLE;
        end

        default: begin
          state <= IDLE;
        end

      endcase
    end
  end

  assign out_X = reg_X_1;
  assign out_Y = reg_Y_1;
  assign out_Z = reg_Z_1;
  assign out_Q = reg_Q_1;

  // observe_type:
  // 00 = Adder
  // 01 = Subtractor
  // 10 = Multiplier

  always @(*) begin
    observe_data = 16'd0;

    case (observe_type)
      2'b00: begin
        case (observe_index)
          8'd0: observe_data = adder_0_result;
          default: begin end
        endcase
      end
      2'b01: begin
        case (observe_index)
          8'd0: observe_data = subtractor_0_result;
          default: begin end
        endcase
      end
      2'b10: begin
        case (observe_index)
          8'd0: observe_data = multiplier_0_result;
          default: begin end
        endcase
      end
      default: begin end
    endcase
  end

endmodule
